// HasEscrow applies the HasEdge predicate on the "escrow" edge.
func HasEscrow() predicate.PendingRefund {
	return predicate.PendingRefund(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, EscrowTable, EscrowColumn),
		)
		schemaConfig := internal.SchemaConfigFromContext(s.Context())
		step.To.Schema = schemaConfig.Escrow
		step.Edge.Schema = schemaConfig.PendingRefund
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEscrowWith applies the HasEdge predicate on the "escrow" edge with a given conditions (other predicates).
func HasEscrowWith(preds ...predicate.Escrow) predicate.PendingRefund {
	return predicate.PendingRefund(func(s *sql.Selector) {
		step := newEscrowStep()
		schemaConfig := internal.SchemaConfigFromContext(s.Context())
		step.To.Schema = schemaConfig.Escrow
		step.Edge.Schema = schemaConfig.PendingRefund
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PendingRefund) predicate.PendingRefund {
	return predicate.PendingRefund(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PendingRefund) predicate.PendingRefund {
	return predicate.PendingRefund(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PendingRefund) predicate.PendingRefund {
	return predicate.PendingRefund(sql.NotPredicates(p))
}
